import csv
import io
import re
import typing


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str) or not raw_csv:
        return {"columns": [], "rows": []}

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        records = [list(row) for row in reader]
    except (csv.Error, TypeError, ValueError):
        records = []
        for line in raw_csv.splitlines():
            records.append(line.split(","))

    expected_width = 9
    nonempty = [(i, row) for i, row in enumerate(records) if any(x != "" for x in row)]

    def header_score(row: typing.List[str]) -> float:
        if len(row) != expected_width:
            return -1.0
        values = [value.strip() for value in row]
        if not any(values):
            return -1.0

        score = 0.0
        seen = set()
        for value in values:
            if not value:
                continue
            if value not in seen:
                score += 0.15
            seen.add(value)
            if re.search(r"[A-Za-z]", value):
                score += 1.0
            if re.fullmatch(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)", value):
                score -= 1.5
            elif re.fullmatch(
                r"\d{1,4}[-/]\d{1,2}[-/]\d{1,4}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?",
                value,
            ):
                score -= 1.5
            if re.search(r"[\s_]", value):
                score += 0.1
        return score

    header_index = None
    best_score = float("-inf")

    for position, (index, row) in enumerate(nonempty):
        score = header_score(row)
        if score < 0:
            continue

        following = nonempty[position + 1][1] if position + 1 < len(nonempty) else None
        if following is not None:
            if len(following) == expected_width:
                score += 1.0
            elif len(following) < expected_width:
                score -= 0.5

        if score > best_score:
            best_score = score
            header_index = index

    if header_index is None:
        exact = next(
            (index for index, row in nonempty if len(row) == expected_width),
            None,
        )
        if exact is not None:
            header_index = exact
        elif nonempty:
            header_index = nonempty[0][0]
        else:
            return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[: expected_width - 1] + [
            ",".join(columns[expected_width - 1 :])
        ]

    if columns and columns[0].startswith("\ufeff"):
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for row in records[header_index + 1 :]:
        if not row or not any(value != "" for value in row):
            continue
        if len(row) < expected_width:
            normalized = row + [""] * (expected_width - len(row))
        elif len(row) > expected_width:
            normalized = row[: expected_width - 1] + [
                ",".join(row[expected_width - 1 :])
            ]
        else:
            normalized = row
        rows.append([str(value) for value in normalized])

    return {
        "columns": [str(value) for value in columns],
        "rows": rows,
    }
